`timescale 1fs/1fs
//====================================================================
// pll_rtl_loop -- the generated models, closed around this design's own RTL.
//
// AUTO-GENERATED by spice2rnm (Veylon Systems).  Edits will be overwritten.
//
// NO CO-SIMULATION ANYWHERE IN THIS FILE. The analog is the
//   characterized models composed the way the deck composes them;
//   the digital is the design's own RTL, instantiated unchanged.
//   There is no DPI import, no bridge and no SPICE process, so
//   this runs on one SystemVerilog simulator and nothing else.
//
// WHAT IS STATED, from
//   $HOME/s2r_runs/demo4b_pll_deck/pll_loop.json: which RTL port
//   lands on which net. Connectivity is not recoverable from the
//   models, and a plausible guess wired into a loop is worse than
//   no loop.
//
// WHAT IS DERIVED: the SENSE of every gate the digital side drives
//   -- which logic level makes the loop negative rather than
//   positive. Each one follows from numbers this run measured, and
//   the numbers are quoted with it.
//
// pdn <- up, active HIGH (derived):
//     block 'ro_vco' was measured at 15 control points from 0.495
//       to 2.805 V, over which its frequency falls from 804.5 to
//       16.74 MHz -- Kvco is NEGATIVE (-341 MHz/V end to end)
//     block 'lpfilt': current into 'dra' reaches 'vout' through a
//       state space whose input vector is non-negative throughout
//       (0..2e+08), so positive current RAISES it
//     with cpump quiescent (pupb=1), 'pdn' at 1 drives -0.00447 A
//       into 'dra' and at 0 drives -1.961e-09 A, both measured at
//       1.849 V -- -0.00447 A moves the control down, which is
//       what 'faster' asks, so it is active HIGH
//
// pupb <- dn, active LOW (derived):
//     block 'ro_vco' was measured at 15 control points from 0.495
//       to 2.805 V, over which its frequency falls from 804.5 to
//       16.74 MHz -- Kvco is NEGATIVE (-341 MHz/V end to end)
//     block 'lpfilt': current into 'dra' reaches 'vout' through a
//       state space whose input vector is non-negative throughout
//       (0..2e+08), so positive current RAISES it
//     with cpump quiescent (pdn=0), 'pupb' at 1 drives -1.961e-09
//       A into 'dra' and at 0 drives +0.007103 A, both measured at
//       1.849 V -- +0.007103 A moves the control up, which is what
//       'slower' asks, so it is active LOW
//
//====================================================================
module pll_rtl_loop;
  localparam real VDD       = 3.3;
  // Where an analog output reads as a one. Half the rail the deck
  // declares: characterization measured each switched block at its
  // rails, so that is the level between the two states it knows.
  localparam real VTH       = 1.65;
  localparam real REF_HZ    = 10000000.0;
  localparam real TARGET_HZ = 10000000.0;
  localparam real SETTLE_S  = 2e-05;
  localparam real WINDOW_S  = 5e-06;
  localparam real TOL_FRAC  = 0.02;

  //------------------------------------------------------------------
  // The analog partition, as analog_top declares its boundary:
  // the nets the deck marks `external` come in as logic, and the
  // nets the digital side reads go out as real volts.
  //------------------------------------------------------------------
  logic pdn;
  logic pupb;
  real  aout_v, dra_v, vout_v;
  analog_top u_analog (
    .pdn(pdn),
    .pupb(pupb),
    .dd_v_ext(),
    .aout_v(aout_v),
    .dra_v(dra_v),
    .vout_v(vout_v)
  );

  //------------------------------------------------------------------
  // The design's own RTL. Nothing here is generated: these are the
  // customer's files, instantiated with the ports the spec names.
  //------------------------------------------------------------------
  logic div_clk, dn, ref_clk, up, vco_clk;

  pfd u_pfd (.div_clk(div_clk), .dn(dn), .ref_clk(ref_clk), .up(up));   // $HOME/s2r_runs/demo4b_pll_deck/pfd.sv
  divn #(.N(40)) u_div (.clk_in(vco_clk), .clk_out(div_clk));   // $HOME/s2r_runs/demo4b_pll_deck/divn.sv

  //------------------------------------------------------------------
  // analog -> digital: the comparator the co-simulation's own
  // testbench would have contained, at the threshold above.
  //------------------------------------------------------------------
  assign vco_clk = (aout_v > VTH);

  //------------------------------------------------------------------
  // digital -> analog: the sense of each of these is DERIVED, and
  // the header quotes the currents and the slope it came from.
  //------------------------------------------------------------------
  assign pdn    = up;      // active HIGH
  assign pupb   = ~dn;     // active LOW

  //------------------------------------------------------------------
  // The reference this loop is asked to follow: 1e+07 Hz, so a half
  // period of 50000000 fs at this file's own precision.
  //------------------------------------------------------------------
  initial ref_clk = 1'b0;
  always #(50000000) ref_clk = ~ref_clk;

  //------------------------------------------------------------------
  // WHAT IS MEASURED. Every analog net is watched on every change
  // it makes rather than on a tick: a switched node aliases
  // against an even stride, and the pump's own driven node is one.
  //
  // Each net reports the range it covered inside the window and how
  // far it moved from one end of the window to the other. The second
  // is a SETTLING measure and it is meaningless for a net that
  // switches -- a square wave at the same level at both ends has
  // moved nothing and settled nothing. The range beside it is what
  // says which kind of net this is.
  //
  // The rate is taken from the FIRST and LAST edge inside the
  // window, not from the count alone. Counting div_clk at 1e+07 Hz over
  // 5e-06 s gives about 50 edges, and +/-1 edge on that is 2.000% --
  // the same size as the tolerance it would be judged against.
  //------------------------------------------------------------------
  int unsigned __edges;
  real         __t_first, __t_last;
  logic        __counting = 1'b0;
  always @(posedge div_clk) begin
    if (__counting) begin
      if (__edges == 0) __t_first = $realtime;
      __t_last = $realtime;
      __edges  = __edges + 1;
    end
  end

  real  __lo_aout = 1.0e308, __hi_aout = -1.0e308;
  real  __at_aout;
  logic __bad_aout = 1'b0;
  always @(aout_v) begin
    if (!(aout_v > -1.0e308 && aout_v < 1.0e308)) __bad_aout = 1'b1;
    else if (__counting) begin
      if (aout_v < __lo_aout) __lo_aout = aout_v;
      if (aout_v > __hi_aout) __hi_aout = aout_v;
    end
  end
  real  __lo_dra = 1.0e308, __hi_dra = -1.0e308;
  real  __at_dra;
  logic __bad_dra = 1'b0;
  always @(dra_v) begin
    if (!(dra_v > -1.0e308 && dra_v < 1.0e308)) __bad_dra = 1'b1;
    else if (__counting) begin
      if (dra_v < __lo_dra) __lo_dra = dra_v;
      if (dra_v > __hi_dra) __hi_dra = dra_v;
    end
  end
  real  __lo_vout = 1.0e308, __hi_vout = -1.0e308;
  real  __at_vout;
  logic __bad_vout = 1'b0;
  always @(vout_v) begin
    if (!(vout_v > -1.0e308 && vout_v < 1.0e308)) __bad_vout = 1'b1;
    else if (__counting) begin
      if (vout_v < __lo_vout) __lo_vout = vout_v;
      if (vout_v > __hi_vout) __hi_vout = vout_v;
    end
  end

  real  __hz, __err;
  logic __locked, __finite = 1'b1;
  initial begin
    #(20000000000);
    __at_aout = aout_v;
    __at_dra = dra_v;
    __at_vout = vout_v;
    __edges    = 0;
    __counting = 1'b1;
    #(5000000000);
    __counting = 1'b0;

    $display("[rtl-loop] %s: %0.6g s of settling, then a %0.6g s window", "pll_rtl_loop", SETTLE_S, WINDOW_S);
    $display("[rtl-loop] net %-8s %10.6f .. %10.6f V   moved %+10.3e V across the window%s", "aout", __lo_aout, __hi_aout, aout_v - __at_aout, __bad_aout ? "   NOT FINITE" : "");
    if (__bad_aout) __finite = 1'b0;
    $display("[rtl-loop] net %-8s %10.6f .. %10.6f V   moved %+10.3e V across the window%s", "dra", __lo_dra, __hi_dra, dra_v - __at_dra, __bad_dra ? "   NOT FINITE" : "");
    if (__bad_dra) __finite = 1'b0;
    $display("[rtl-loop] net %-8s %10.6f .. %10.6f V   moved %+10.3e V across the window%s", "vout", __lo_vout, __hi_vout, vout_v - __at_vout, __bad_vout ? "   NOT FINITE" : "");
    if (__bad_vout) __finite = 1'b0;

    if (__edges < 2) begin
      $display("[rtl-loop] rate   %s produced %0d edge(s) in the window -- too few to time", "div_clk", __edges);
      __hz     = 0.0;
      __err    = 1.0;
      __locked = 1'b0;
    end else begin
      // seconds between the first and last edge counted, from the
      // 1 fs timestamps this file is compiled at
      __hz     = (real'(__edges) - 1.0) / ((__t_last - __t_first) * 1.0e-15);
      __err    = (__hz - TARGET_HZ) / TARGET_HZ;
      __locked = (__err > -TOL_FRAC) && (__err < TOL_FRAC);
      $display("[rtl-loop] rate   %s %0.6f MHz against %0.6f MHz asked for  (%+0.4f%%, tolerance %0.3f%%)  %s  [%0d edges]", "div_clk", __hz / 1.0e6, TARGET_HZ / 1.0e6, __err * 100.0, TOL_FRAC * 100.0, __locked ? "LOCKED" : "NOT LOCKED", __edges);
    end

    //----------------------------------------------------------------
    // The verdict covers what it says and no more: this loop, at
    // this reference, from the initial condition the deck states.
    // It is not evidence about the transistors -- there are none
    // in this flow -- and a loop that settles somewhere plausible
    // and wrong still settles.
    //----------------------------------------------------------------
    $display("[rtl-loop] VERDICT %s", (__locked && __finite) ? "PASS" : "FAIL");
    $finish;
  end
endmodule : pll_rtl_loop
